import React, { useEffect, useState } from "react";
import MenuCard from "./MenuCard";

const MenuGrid = ({ addToCart }) => {
  const [menuItems, setMenuItems] = useState([]);
  const [colleges, setColleges] = useState([]);
  const [selectedCollege, setSelectedCollege] = useState("");

  // Fetch colleges
  useEffect(() => {
    fetch("http://127.0.0.1:8000/colleges/")
      .then((res) => res.json())
      .then((data) => setColleges(data))
      .catch((err) => console.error(err));
  }, []);

  // Fetch menu only after college selection
  useEffect(() => {
    if (!selectedCollege) {
      setMenuItems([]);
      return;
    }

    fetch(
      `http://127.0.0.1:8000/menu/?college=${encodeURIComponent(
        selectedCollege
      )}`
    )
      .then((res) => res.json())
      .then((data) => setMenuItems(data))
      .catch((err) => console.error(err));
  }, [selectedCollege]);

  return (
    <div className="menu-container">
      {/* College Dropdown */}
      <div style={{ textAlign: "center", marginBottom: "20px" }}>
        <select
          value={selectedCollege}
          onChange={(e) => setSelectedCollege(e.target.value)}
          style={{
            padding: "10px",
            fontSize: "16px",
            borderRadius: "6px",
            minWidth: "220px",
          }}
        >
          <option value="" disabled>
            Select College
          </option>
          {colleges.map((college, index) => (
            <option key={index} value={college}>
              {college}
            </option>
          ))}
        </select>
      </div>

      {/* Menu Items */}
      <div className="menu-grid">
        {!selectedCollege ? (
          <p style={{ textAlign: "center" }}>
            Please select a college to view menu
          </p>
        ) : menuItems.length > 0 ? (
          menuItems.map((item) => (
            <MenuCard
              key={item.id}
              item={item}
              addToCart={addToCart}
            />
          ))
        ) : (
          <p style={{ textAlign: "center" }}>
            No items available for this college
          </p>
        )}
      </div>
    </div>
  );
};

export default MenuGrid;
